diff --git a/src/tags.mjs b/src/tags.mjs
index a1a201c..a8ef419 100644
--- a/src/tags.mjs
+++ b/src/tags.mjs
@@ -1,3 +1,13 @@
 export function parseTags(value) {
-  return value;
+  const seen = new Set();
+  const tags = [];
+  for (const entry of value.split(",")) {
+    const tag = entry.trim();
+    const key = tag.toLowerCase();
+    if (tag && !seen.has(key)) {
+      seen.add(key);
+      tags.push(tag);
+    }
+  }
+  return tags;
 }

diff --git a/src/tags.mjs b/src/tags.mjs
