+++ b/src/tags.mjs
@@ -1,3 +1,9 @@
 export function parseTags(value) {
-  return value;
+  const seen = new Set();
+  return value.split(",").map(tag => tag.trim()).filter(tag => {
+    const key = tag.toLowerCase();
+    if (!tag || seen.has(key)) return false;
+    seen.add(key);
+    return true;
+  });
 }

